def planned_set_id(program_exercise_id: UUID, position: int) -> UUID:
    digest = hashlib.sha256(program_exercise_id.bytes + position.to_bytes(2, "big")).digest()
    return UUID(bytes=digest[:16], version=4)


def targets_to_planned_sets(apps: Apps, schema_editor: BaseDatabaseSchemaEditor) -> None:
    ProgramExercise = apps.get_model("training", "ProgramExercise")
    ProgramSet = apps.get_model("training", "ProgramSet")
    ProgramSet.objects.bulk_create(
        ProgramSet(
            id=planned_set_id(planned.pk, position),
            program_exercise_id=planned.pk,
            position=position,
            set_type="normal",
            reps=planned.target_reps,
        )
        for planned in ProgramExercise.objects.all()
        for position in range(planned.target_sets)
    )


